<script setup lang="ts">
import type { JsonValue } from '~/types/generation'
import { teacherField, teacherError } from '~/utils/teacher-language'
const props = defineProps<{ value: JsonValue; path: string; label: string; disabled?: boolean; errors?: { field: string; message: string }[] }>()
const emit = defineEmits<{ update: [value: JsonValue] }>()
const labels: Record<string,string> = { personal:'Личностные', meta_subject:'Метапредметные', subject_specific:'Предметные', title:'Название', teacher_actions:'Действия педагога', student_actions:'Действия участников', dialogue_prompts:'Вопросы для обсуждения', teacher_tips:'Подсказки педагогу', transition_text:'Переход к следующему этапу', duration_minutes:'Продолжительность, минут', stage_type:'Тип этапа', presentation_slides:'Слайды', printable_cards:'Карточки', handouts:'Раздаточные листы', slide_number:'Номер слайда', bullet_points:'Тезисы', visual_recommendations:'Визуальные рекомендации', speaker_notes:'Текст выступления', card_type:'Тип карточки', front_text:'Лицевая сторона', back_text:'Оборотная сторона', quantity_per_group:'На одну группу', instructions:'Инструкция', template_content:'Шаблон' }
const hidden = ['id','order_index','stage_identifier','target_stage_id']
function replace(key: string | number, value: JsonValue) { const next = Array.isArray(props.value) ? [...props.value] : { ...(props.value as Record<string,JsonValue>) }; (next as Record<string|number,JsonValue>)[key] = value; emit('update', next) }
const types = [{value:'organizational_moment',label:'Организационный момент'},{value:'motivation_introduction',label:'Введение и мотивация'},{value:'main_interactive_part',label:'Основная интерактивная часть'},{value:'practical_task',label:'Практическая задача'},{value:'reflection_summary',label:'Итоговая рефлексия'},{value:'ritual_conclusion',label:'Завершение'}]
</script>
<template><div class="revision-fields"><template v-if="Array.isArray(value)"><h3>{{ label }}</h3><div v-for="(item,i) in value" :key="i" class="revision-field-item"><RevisionFields :value="item" :path="`${path}.${i}`" :label="`${label} ${i+1}`" :disabled="disabled" :errors="errors" @update="replace(i,$event)" /></div></template><template v-else-if="value && typeof value === 'object'"><h3>{{ label }}</h3><template v-for="(item,key) in value" :key="key"><RevisionFields v-if="!hidden.includes(String(key))" :value="item" :path="`${path}.${key}`" :label="labels[String(key)] ?? teacherField(String(key))" :disabled="disabled" :errors="errors" @update="replace(String(key),$event)" /></template></template><label v-else-if="typeof value === 'boolean'" class="constructor-check"><input type="checkbox" :checked="value" :disabled="disabled" @change="emit('update',($event.target as HTMLInputElement).checked)">{{ label }}</label><UiSelect v-else-if="path.endsWith('.stage_type')" :model-value="String(value)" :label="label" :options="types" :disabled="disabled" :error="teacherError(errors, path)" @update:model-value="emit('update',$event)" /><UiField v-else-if="typeof value === 'number'" :model-value="String(value)" type="number" :label="label" :disabled="disabled" :min="path.endsWith('.duration_minutes') ? 2 : 1" :max="path.endsWith('.duration_minutes') ? 120 : undefined" :error="teacherError(errors, path)" @update:model-value="emit('update',Number($event))" /><UiTextarea v-else :model-value="value == null ? '' : String(value)" :label="label" :disabled="disabled" :error="teacherError(errors, path)" rows="3" @update:model-value="emit('update',$event)" /></div></template>
